MM.mnemo[17] = {"cards":[{"id":"ko-k3-0299","w":"배우다","cs":"učit se (dovednost / od někoho)","en":"to learn","p":"v","o":"k","ex":"일본어를 배우기 위해서","exc":"aby se naučil japonsky; za účelem studia japonštiny (를 → 4. pád; -기 위해서 → aby)","m":"Znamená ‚učit se‘ novou dovednost či jazyk od někoho nebo ze zdroje (opak 가르치다 = učit někoho). Samostatné studium z knih je 공부하다."},{"id":"ko-k3-0300","w":"받다","cs":"dostat; obdržet; přijmout","en":"to receive","p":"v","o":"k","ex":"장학금을 받기 위해서 열심히 공부해요.","exc":"Pilně se učím, abych dostal stipendium. (을 → 4. pád; -기 위해서 → aby)","exa":"장학금을 받기 위해서 열심히 공부해요. ⚠","m":"Výslovnost [받따]. Opak slovesa 주다 (dát). Častá spojení: 선물을 받다 (dostat dárek), 전화를 받다 (zvednout telefon).","tv":["받아요","받았어요","받을 거예요"]},{"id":"ko-k3-0301","w":"준비하다","cs":"připravit; nachystat","en":"to prepare","p":"v","o":"s","ex":"친구를 위해서 선물을 준비했어요.","exc":"Připravil jsem pro kamaráda dárek. (를 → 4. pád; -을 위해서 → pro)","m":"準 připravit, norma + 備 vybavit + 하다 dělat = nachystat a vybavit vše potřebné, tedy připravit. Podstatné jméno je 준비 (příprava).","r":["jun-準","bi-備"]},{"id":"ko-k3-0302","w":"건강","cs":"zdraví","en":"health","p":"n","o":"s","ex":"건강을 위해서 매일 운동하고 있어요.","exc":"Pro své zdraví každý den cvičím. (을 → 4. pád; -을 위해서 → pro; -고 있다 → právě dělat)","m":"健 zdravý, silný + 康 zdraví, klid = tělesná i duševní pohoda, tedy zdraví. Přídavné jméno 건강하다 = být zdravý; přípitek ‚Na zdraví!‘ je 건강을 위하여!.","hada":1,"r":["geon-健","gang-康"]},{"id":"ko-k3-0303","w":"평화","cs":"mír; klid","en":"peace","p":"n","o":"s","ex":"슈퍼맨은 세계 평화를 위해서 일해요.","exc":"Superman pracuje pro světový mír. (은 → téma; 를 → 4. pád; -를 위해서 → pro)","m":"平 rovný, klidný + 和 mír, soulad = vyrovnaný soulad bez bojů, tedy mír. Přídavné jméno je 평화롭다 (mírumilovný, poklidný).","r":["pyeong-平","hwa-和"]},{"id":"ko-k3-0304","w":"부모님","cs":"rodiče","en":"parents","p":"n","o":"m","ex":"부모님을 위해서 돈을 모았어요.","exc":"Našetřil jsem peníze pro rodiče. (을 → 4. pád; -을 위해서 → pro)","m":"父 otec + 母 matka + uctivá přípona 님 = rodiče. Stejná přípona 님 je i v 선생님 (učitel) nebo 사장님 (šéf).","r":["bu-父","mo-母"]},{"id":"ko-k3-0305","w":"미래","cs":"budoucnost","en":"future","p":"n","o":"s","ex":"미래를 위해서 돈을 모으고 있어요.","exc":"Šetřím peníze na budoucnost. (를 위해서 → pro)","m":"未 ještě ne + 來 přijít = to, co ještě nepřišlo. Opak 과거 (minulost).","r":["mi-未","rae-來"]},{"id":"ko-k3-0306","w":"피부","cs":"pleť, kůže","en":"skin","p":"n","o":"s","ex":"저는 피부를 위해서 물을 많이 마셔요.","exc":"Kvůli pleti piju hodně vody. (를 위해서 → kvůli)","m":"皮 kůže + 膚 pokožka. 피부과 = kožní oddělení.","r":["pi-皮","bu-膚"]},{"id":"ko-k3-0307","w":"가족","cs":"rodina","en":"family","p":"n","o":"s","ex":"가족들한테 보내기 위해서 편지를 썼어요.","exc":"Napsal jsem dopis, abych ho poslal rodině. (들 → množné číslo; 한테 → komu; -기 위해서 → aby)","m":"家 dům + 族 rod = lidé patřící k jednomu domu a rodu, tedy rodina. 家 jako v 가구 (nábytek) nebo 국가 (stát).","r":["ga-家","jok-族"]},{"id":"ko-k3-0308","w":"손님","cs":"zákazník; host","en":"customer","p":"n","o":"k","ex":"손님들을 위해서 화분이 하나 필요합니다.","exc":"Pro zákazníky je potřeba jeden květináč. (들 → množné číslo; -을 위해서 → pro; 이 → 1. pád)","exa":"손님들을 위해서 화분이 하나 필요합니다. ⚠","m":"Složené ze staršího základu 손 (host) + uctivá přípona 님 = host (na návštěvě) nebo zákazník (v obchodě či restauraci)."},{"id":"ko-k3-0309","w":"위하다","cs":"dělat pro (někoho/něco); pečovat o","en":"to do something for (the benefit of) someone","p":"v","o":"s","rz":["위해 = 위하여, 위해서 = 위하여서","위해 = 위하여 (pro), 위해서 = 위하여서 (za účelem, aby)"],"m":"爲 dělat, pro + 하다 dělat = jednat ve prospěch někoho. V praxi se téměř vždy používá ve vazbách -을/를 위해서 (pro někoho) a -기 위해서 (aby).","r":["wi-爲"]},{"id":"ko-k3-0310","w":"세계","cs":"svět","en":"world","p":"n","o":"s","ex":"슈퍼맨은 세계 평화를 위해서 일해요.","exc":"Superman pracuje pro světový mír. (은 → téma; 를 → 4. pád; -를 위해서 → pro)","m":"世 svět, generace + 界 hranice, sféra = celý lidský svět. Častá spojení: 세계 여행 (cesta kolem světa), 전 세계 (celý svět).","r":["se-世","gye-界"]},{"id":"ko-k3-0313","w":"배낭여행","cs":"cestování s batohem","en":"backpacking trip","p":"n","o":"s","ex":"유럽으로 배낭여행을 가기 위해서 돈을 모으고 있어요.","exc":"Šetřím peníze, abych mohl jet s batohem po Evropě. (-기 위해서 → aby)","m":"背 záda + 囊 vak = batoh + 旅行 cesta. Levné cestování jen s batohem.","r":["bae-背","nang-囊","yeo-旅","haeng-行"]},{"id":"ko-k3-0314","w":"여름 방학","cs":"letní prázdniny (školní)","en":"summer vacation","p":"f","o":"m","ex":"이번 여름 방학 때 갈 거예요.","exc":"Pojedu tam o těchto letních prázdninách. (때 → kdy, v době; -ㄹ 거예요 → budu)","m":"Složené z 여름 (léto) + 방학 (školní prázdniny: 放 uvolnit, pustit + 學 škola). Na rozdíl od 휴가 (dovolená v práci) se 방학 používá jen pro školní prázdniny.","r":["bang-放","hak-學"]},{"id":"ko-k3-0315","w":"선물","cs":"dárek; dar","en":"present, gift","p":"n","o":"s","ex":"친구를 위해서 선물을 준비했어요.","exc":"Připravil jsem pro kamaráda dárek. (를 → 4. pád; -을 위해서 → pro)","m":"膳 dar, pokrm + 物 věc = darovaná věc, tedy dárek. 物 jako v 동물 (zvíře) nebo 물건 (věc). Sloveso 선물하다 = darovat.","hada":1,"r":["seon-膳","mul-物"]},{"id":"ko-k3-0316","w":"요리","cs":"vaření; jídlo (pokrm)","en":"cooking","p":"n","o":"s","ex":"부모님을 위해서 요리를 할 거예요.","exc":"Uvařím pro rodiče. (을 위해서 → pro)","m":"料 přísada + 理 uspořádat = dát přísady dohromady. 요리하다 = vařit, 요리사 = kuchař.","hada":1,"r":["yo-料","ri-理"]},{"id":"ko-k3-0317","w":"대학","cs":"vysoká škola; univerzita","en":"college, university","p":"n","o":"s","ex":"대학에 가기 위해서 열심히 공부하고 있어요.","exc":"Pilně se učím, abych se dostal na vysokou školu. (에 → kam; -기 위해서 → aby; -고 있다 → právě dělat)","m":"大 velký + 學 učení, škola = velká (vyšší) škola, tedy vysoká škola nebo univerzita. Často také v delším tvaru 대학교; vysokoškolák je 대학생.","r":["dae-大","hak-學"]},{"id":"ko-k3-0318","w":"일찍","cs":"brzy; časně","en":"early","p":"o","o":"k","ex":"내일 일찍 일어나기 위해서 지금 잘 거예요.","exc":"Půjdu teď spát, abych zítra brzy vstal. (-기 위해서 → aby; -ㄹ 거예요 → budu)","m":"Stojí před slovesem (일찍 일어나다 = brzy vstát, 일찍 자다 = jít brzy spát). Opak 늦게 (pozdě)."},{"id":"ko-k3-0319","w":"편지","cs":"dopis","en":"letter","p":"n","o":"s","ex":"가족들한테 보내기 위해서 편지를 썼어요.","exc":"Napsal jsem dopis, abych ho poslal rodině. (들 → množné číslo; 한테 → komu; -기 위해서 → aby)","m":"片 kousek, lístek + 紙 papír = popsaný list papíru, tedy dopis. Častá spojení: 편지를 쓰다 (psát dopis), 편지를 보내다 (poslat dopis).","r":["pyeon-片","ji-紙"]},{"id":"ko-k3-0320","w":"빨리","cs":"rychle","en":"quickly, fast","p":"o","o":"k","ex":"빨리 가기 위해서 택시를 탔어요.","exc":"Vzal jsem si taxík, abych tam byl rychle. (-기 위해서 → aby; 를 → 4. pád)","m":"Příslovce od přídavného jména 빠르다 (rychlý). Fráze 빨리빨리! (Rychle, rychle!) je symbolem pověstného korejského tempa. Opak 천천히 (pomalu)."}],"gram":{"id":"ko-k3-g17","w":"위해, 위해서","en":"In order to, For the sake of","cs":"pro, kvůli, za účelem; aby…","vy":"Vzorec 위해 (hovorově také 위해서, původně 위하여) vyjadřuje účel nebo prospěch (‚pro…, kvůli…, aby…‘). Za podstatným jménem stojí s pádovou částicí -을/를 (např. 건강을 위해서 = pro zdraví). U sloves se kmen nejprve převede na podstatné jméno pomocí koncovky -기 a teprve za ni následuje 위해서 (např. 가기 위해서 = abych jel / za účelem cesty).","m":"Pochází ze slovesa 위하다 (pečovat, jednat v zájmu někoho) + koncovka -아서/어서. Pozor na vazbu: po podstatném jménu vyžaduje 4. pád (-을/를 위해서), zatímco po slovese vyžaduje -기 (-기 위해서).","s":[["위해 = 위하여 · 위해서 = 위하여서","za účelem; pro; kvůli (위하여 je původní vyčasovaný tvar)"],["건강을 위해서","pro zdraví; kvůli zdraví; aby byl člověk zdravý"],["회사를 위해서","pro firmu; v zájmu firmy"],["한국에 가기 위해서","aby jel do Koreje / za účelem cesty do Koreje"],["일본어를 배우기 위해서","aby se naučil japonsky / kvůli studiu japonštiny"],["슈퍼맨은 세계 평화를 위해서 일해요.","Superman pracuje pro světový mír."],["저는 한국에 가기 위해서 열심히 공부했어요.","Pilně jsem se učil, abych mohl jet do Koreje."],["부모님을 위해서 돈을 모았어요.","Našetřil jsem peníze pro rodiče."],["건강을 위해서 매일 운동하고 있어요.","Pro své zdraví cvičím každý den."],["유럽으로 배낭여행을 가기 위해서 돈을 모으고 있어요.","Šetřím peníze, abych mohl jet s batohem po Evropě."],["친구를 위해서 선물을 준비했어요.","Připravil jsem dárek pro kamaráda."],["청소를 하기 위해서 창문을 열었어요.","Otevřel jsem okno, abych mohl uklidit."],["내일 일찍 일어나기 위해서 지금 잘 거예요.","Půjdu teď spát, abych zítra brzy vstal."],["빨리 가기 위해서 택시를 탔어요.","Vzal jsem si taxík, abych tam byl rychle."],["저는 피부를 위해서 물을 많이 마셔요.","Piju hodně vody kvůli pleti."],["가족들한테 보내기 위해서 편지를 썼어요.","Napsal jsem dopis, abych ho poslal rodině."]]}};
Object.assign(MM.mnRoots, {"jun-準":["준","準","připravit, norma"],"bi-備":["비","備","vybavit, připravit"],"geon-健":["건","健","zdravý, silný"],"gang-康":["강","康","zdraví, klid"],"pyeong-平":["평","平","rovný, běžný"],"hwa-和":["화","和","mír, soulad, harmonie"],"bu-父":["부","父","otec"],"mo-母":["모","母","matka"],"mi-未":["미","未","ještě ne"],"rae-來":["래","來","přijít"],"pi-皮":["피","皮","kůže"],"bu-膚":["부","膚","pokožka"],"ga-家":["가","家","dům, rodina"],"jok-族":["족","族","rod"],"wi-爲":["위","爲","dělat, pro (prospěch)"],"se-世":["세","世","svět, věk, generace"],"gye-界":["계","界","hranice, svět, sféra"],"bae-背":["배","背","záda"],"nang-囊":["낭","囊","vak, měšec"],"yeo-旅":["여","旅","cesta, cestovat"],"haeng-行":["행","行","jít, konat"],"bang-放":["방","放","pustit, vysílat"],"hak-學":["학","學","učení, škola"],"seon-膳":["선","膳","pokrm, dar"],"mul-物":["물","物","věc"],"yo-料":["요","料","přísada, materiál"],"ri-理":["리","理","uspořádat, princip"],"dae-大":["대","大","velký"],"pyeon-片":["편","片","kousek, lístek"],"ji-紙":["지","紙","papír"]});
